# Generates newlossnumbers.tex and the three new-loss tables from the result files.
# Run from this folder:  python3 gen_newloss_numbers.py
#
# Inputs  : ../gpu code results/new losses/*.json   (CORN, RANK, PLR; TSOFT12, LBL10 and WKL
#                                                   are added automatically when present)
#           ../gpu code results/{MSE,CORAL}.json    (the matched v3 controls)
# Outputs : newlossnumbers.tex, tablenewlossdev.tex, tablenewlosstest.tex, tablenewlossdelta.tex
# Every number in those files is read from the JSON files. Do not edit them by hand.

import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
NEW = HERE.parent / "gpu code results" / "new losses"
V3 = HERE.parent / "gpu code results"

# arm -> (macro suffix, table label, matched control arm in v3, control label)
NEW_ARMS = {
    "CORN":    ("Corn",  "CORN",                         "CORAL", "CORAL"),
    "RANK":    ("Rank",  "MSE + margin ranking (RANK)",  "MSE",   "Regression (MSE)"),
    "PLR":     ("Plr",   "MSE + pairwise logistic (PLR)", "MSE",  "Regression (MSE)"),
    "TSOFT12": ("Tsoft", "Truncated soft labels (TSOFT12)", "SOFT2", "SOFT ($\\beta=2$)"),
    "LBL10":   ("Lbl",   "Length-balanced loss (LBL10)",  "CE",    "CE"),
    "WKL":     ("Wkl",   "Weighted kappa loss (WKL)",     "CE",    "CE"),
}
CONTROLS = {"MSE": ("Mse", "Regression (MSE)"), "CORAL": ("Coral", "CORAL"),
            "CE": ("Ce", "CE"), "SOFT2": ("SoftTwo", "SOFT ($\\beta=2$)")}
METRICS = [("qwk", "Qwk", 2), ("acc19", "Acc", 2), ("acc19_pm1", "Pm", 2), ("dist", "Dist", 3),
           ("acc7", "AccSeven", 2), ("acc5", "AccFive", 2), ("acc3", "AccThree", 2),
           ("far_ge3", "FarThree", 2), ("far_ge5", "FarFive", 2), ("macro_f1", "Mf", 2)]


def val(res, split, key, nd):
    v = res[split][key]
    return round(v, nd) if key == "dist" else round(100 * v, nd)


def fmt(x, nd):
    return f"{x:.{nd}f}"


def signed(x, nd=2):
    return f"{'+' if x >= 0 else '-'}{abs(x):.{nd}f}"


def load(path):
    return json.loads(Path(path).read_text())


present = {a: load(NEW / f"{a}.json") for a in NEW_ARMS if (NEW / f"{a}.json").exists()}
controls = {a: load(V3 / f"{a}.json") for a in CONTROLS if (V3 / f"{a}.json").exists()}
assert present, f"no new-loss result files in {NEW}"

lines = ["% Generated from the new-loss result files by gen_newloss_numbers.py. Do not edit by hand.",
         f"% New-loss runs found: {', '.join(present)}", ""]
for arm, res in present.items():
    suf = NEW_ARMS[arm][0]
    for split, sp in (("dev", "Dev"), ("test", "Test")):
        for key, mk, nd in METRICS:
            lines.append(f"\\newcommand{{\\nl{sp}{mk}{suf}}}{{{fmt(val(res, split, key, nd), nd)}}}")
    lines.append(f"\\newcommand{{\\nlSel{suf}}}{{{int(res['selected_epoch'])}}}")
    lines.append(f"\\newcommand{{\\nlMin{suf}}}{{{res['minutes']:.0f}}}")
    abl = res.get("ablation_qwk_selected")
    if abl:
        lines.append(f"\\newcommand{{\\nlQwkselEpoch{suf}}}{{{int(abl['selected_epoch'])}}}")
        lines.append(f"\\newcommand{{\\nlQwkselTestQwk{suf}}}{{{fmt(100 * abl['test']['qwk'], 2)}}}")
        lines.append(f"\\newcommand{{\\nlQwkselTestGain{suf}}}"
                     f"{{{signed(100 * (abl['test']['qwk'] - res['test']['qwk']))}}}")
    ctrl = NEW_ARMS[arm][2]
    if ctrl in controls:
        c = controls[ctrl]
        for split, sp in (("dev", "Dev"), ("test", "Test")):
            for key, mk, nd in METRICS:
                if key == "dist":
                    continue
                d = 100 * (res[split][key] - c[split][key])
                lines.append(f"\\newcommand{{\\nlDelta{sp}{mk}{suf}}}{{{signed(d)}}}")
                lines.append(f"\\newcommand{{\\nlAbsDelta{sp}{mk}{suf}}}{{{abs(d):.2f}}}")
    lines.append("")

# run checks over all present new-loss runs
all_ok = all(r.get("steps_per_epoch_ok") and r.get("realised_train_batch") == 64
             and (r.get("selection_check") or {}).get("exact")
             and (r.get("provenance") or {}).get("n_gpu") == 1 for r in present.values())
lines.append(f"\\newcommand{{\\nlChecksPass}}{{{'yes' if all_ok else 'NO'}}}")
lines.append(f"\\newcommand{{\\nlRuns}}{{{len(present)}}}")
lines.append(f"\\newcommand{{\\nlTotalMinutes}}{{{sum(r['minutes'] for r in present.values()):.0f}}}")
tfv = sorted({(r.get('provenance') or {}).get('transformers') for r in present.values()})
lines.append(f"\\newcommand{{\\nlTfVersion}}{{{', '.join(v for v in tfv if v)}}}")
(HERE / "newlossnumbers.tex").write_text("\n".join(lines) + "\n")


def row(label, res, split, ep):
    cells = [fmt(val(res, split, k, nd), nd) for k, _, nd in METRICS]
    return f"{label} & " + " & ".join(cells) + f" & {ep} \\\\"


def table(split, name):
    out = ["% generated by gen_newloss_numbers.py", "\\begin{table}[H]", "\\centering", "\\footnotesize",
           f"\\caption{{Loss functions from readability research in other languages, on the BAREC "
           f"{'development' if split == 'dev' else 'test'} set, beside their matched controls from "
           f"Table~\\ref{{tab:res-main-{split}}}. Same pipeline, one head and one loss changed.}}",
           f"\\label{{tab:res-newloss-{split}}}",
           "\\begin{adjustbox}{max width=\\textwidth}", "\\begin{tabular}{lrrrrrrrrrrr}", "\\toprule",
           "\\textbf{Method} & \\textbf{QWK} & \\textbf{Acc19} & \\textbf{$\\pm$1} & \\textbf{Dist} & "
           "\\textbf{Acc7} & \\textbf{Acc5} & \\textbf{Acc3} & \\textbf{far$\\geq$3} & "
           "\\textbf{far$\\geq$5} & \\textbf{mF1} & \\textbf{Ep.} \\\\", "\\midrule",
           "\\multicolumn{12}{l}{\\textit{Controls from the comparable group}} \\\\", "\\midrule"]
    for c in ("MSE", "CORAL"):
        if c in controls:
            out.append(row(CONTROLS[c][1], controls[c], split, int(controls[c]["selected_epoch"])))
    out += ["\\midrule", "\\multicolumn{12}{l}{\\textit{Loss functions added in this thesis}} \\\\", "\\midrule"]
    for arm, res in present.items():
        out.append(row(NEW_ARMS[arm][1], res, split, int(res["selected_epoch"])))
    out += ["\\bottomrule", "\\end{tabular}", "\\end{adjustbox}", "", "\\vspace{0.1cm}",
            "{\\footnotesize QWK, the accuracies, far$\\geq$3, far$\\geq$5 and macro-F1 are percentages; "
            "Dist is in levels; Ep.\\ is the selected epoch. far$\\geq$3 and far$\\geq$5 are this thesis's "
            "own metrics.}", "\\end{table}"]
    (HERE / name).write_text("\n".join(out) + "\n")


table("dev", "tablenewlossdev.tex")
table("test", "tablenewlosstest.tex")

# delta table: each new loss minus its matched control, both splits
out = ["% generated by gen_newloss_numbers.py", "\\begin{table}[H]", "\\centering", "\\footnotesize",
       "\\caption{Each added loss minus its matched control, in percentage points. A positive QWK or "
       "Acc19 difference is better; a negative far-miss difference is better. One seed per method.}",
       "\\label{tab:res-newloss-delta}", "\\begin{adjustbox}{max width=\\textwidth}",
       "\\begin{tabular}{llrrrrrrrr}", "\\toprule",
       "& & \\multicolumn{4}{c}{\\textbf{development}} & \\multicolumn{4}{c}{\\textbf{test}} \\\\",
       "\\cmidrule(lr){3-6}\\cmidrule(lr){7-10}",
       "\\textbf{Method} & \\textbf{Control} & QWK & Acc19 & far$\\geq$3 & far$\\geq$5 & "
       "QWK & Acc19 & far$\\geq$3 & far$\\geq$5 \\\\", "\\midrule"]
for arm, res in present.items():
    ctrl = NEW_ARMS[arm][2]
    if ctrl not in controls:
        continue
    c = controls[ctrl]
    cells = []
    for split in ("dev", "test"):
        for k in ("qwk", "acc19", "far_ge3", "far_ge5"):
            cells.append(signed(100 * (res[split][k] - c[split][k])))
    out.append(f"{arm} & {NEW_ARMS[arm][3]} & " + " & ".join(cells) + " \\\\")
out += ["\\bottomrule", "\\end{tabular}", "\\end{adjustbox}", "\\end{table}"]
(HERE / "tablenewlossdelta.tex").write_text("\n".join(out) + "\n")

print(f"wrote newlossnumbers.tex and 3 tables for: {', '.join(present)}; checks pass: {all_ok}")
